// Extract and validate application data from webhook payload
const body = $input.first().json.body;

// Validate required fields
if (!body.name || !body.monthly_income) {
  throw new Error('Missing required fields: name and monthly_income are required');
}

// Calculate monthly rent from property data
const monthlyRent = body.property_rent || body.rent_amount || 0;

// Format rental history
const rentalHistory = body.rental_history || [];
const formattedHistory = Array.isArray(rentalHistory) 
  ? rentalHistory.map(r => `${r.address || 'Unknown'} (${r.duration || 'N/A'})`).join('; ')
  : rentalHistory;

// Prepare the prompt for Groq AI
const promptText = `Screen this tenant application:

APPLICATION DATA:
Applicant Name: ${body.name}
Monthly Income: R${body.monthly_income}
Employment Status: ${body.employment_status || 'Not provided'}
Employer: ${body.employer || 'Not provided'}
Employment Duration: ${body.employment_duration || 'Not provided'}
Previous Rentals: ${formattedHistory || 'None'}
Reason for Moving: ${body.reason_for_moving || 'Not provided'}
Number of Occupants: ${body.occupants || 1}
Pets: ${body.pets || 'None'}
Documents Provided: ${Array.isArray(body.documents) ? body.documents.join(', ') : body.documents || 'None'}

Calculate risk and return JSON:
{
  "completeness_score": 0-100,
  "risk_level": "low|medium|high",
  "risk_score": 0-100,
  "affordability_ratio": 0.0-1.0,
  "affordability_status": "excellent|good|fair|poor",
  "red_flags": [
    {
      "flag": "description",
      "severity": "low|medium|high",
      "recommendation": "action to take"
    }
  ],
  "positive_indicators": ["stable employment", etc],
  "recommended_verifications": [
    "employment verification",
    "previous landlord reference",
    etc
  ],
  "document_issues": ["missing payslip", etc],
  "summary": "brief assessment for agent",
  "recommendation": "approve_with_conditions|further_review|reject",
  "confidence": 0.0-1.0
}`;

return [{
  json: {
    application_id: body.application_id || null,
    applicant_name: body.name,
    monthly_income: body.monthly_income,
    monthly_rent: monthlyRent,
    employment_status: body.employment_status,
    employer: body.employer,
    employment_duration: body.employment_duration,
    rental_history: formattedHistory,
    reason_for_moving: body.reason_for_moving,
    occupants: body.occupants || 1,
    pets: body.pets || 'None',
    documents: body.documents || [],
    property_id: body.property_id || null,
    agent_email: body.agent_email || null,
    prompt: promptText,
    raw_payload: body
  }
}];

// Get the AI response and previous node data
const groqResponse = $input.first().json;
const prevData = $input.all()[0].json;

// Extract the JSON content from Groq response
let screeningResult;
try {
  const messageContent = groqResponse.choices?.[0]?.message?.content;
  if (messageContent) {
    screeningResult = JSON.parse(messageContent);
  } else {
    throw new Error('Empty response from Groq AI');
  }
} catch (error) {
  // Fallback if parsing fails
  screeningResult = {
    completeness_score: 50,
    risk_level: 'high',
    risk_score: 75,
    affordability_ratio: 0.5,
    affordability_status: 'unknown',
    red_flags: [{ flag: 'AI parsing error', severity: 'high', recommendation: 'Manual review required' }],
    positive_indicators: [],
    recommended_verifications: ['manual review'],
    document_issues: ['screening failed'],
    summary: 'Error parsing AI response - manual review required',
    recommendation: 'further_review',
    confidence: 0.1
  };
}

// Validate and normalize the response
const result = {
  application_id: prevData.application_id,
  applicant_name: prevData.applicant_name,
  completeness_score: Math.min(100, Math.max(0, screeningResult.completeness_score || 0)),
  risk_level: ['low', 'medium', 'high'].includes(screeningResult.risk_level) ? screeningResult.risk_level : 'high',
  risk_score: Math.min(100, Math.max(0, screeningResult.risk_score || 50)),
  affordability_ratio: Math.min(1, Math.max(0, screeningResult.affordability_ratio || 0.5)),
  affordability_status: screeningResult.affordability_status || 'unknown',
  red_flags: Array.isArray(screeningResult.red_flags) ? screeningResult.red_flags : [],
  positive_indicators: Array.isArray(screeningResult.positive_indicators) ? screeningResult.positive_indicators : [],
  recommended_verifications: Array.isArray(screeningResult.recommended_verifications) ? screeningResult.recommended_verifications : [],
  document_issues: Array.isArray(screeningResult.document_issues) ? screeningResult.document_issues : [],
  summary: screeningResult.summary || 'No summary provided',
  recommendation: ['approve_with_conditions', 'further_review', 'reject'].includes(screeningResult.recommendation) ? screeningResult.recommendation : 'further_review',
  confidence: Math.min(1, Math.max(0, screeningResult.confidence || 0.5)),
  monthly_income: prevData.monthly_income,
  monthly_rent: prevData.monthly_rent,
  agent_email: prevData.agent_email
};

// Flag if high risk for conditional routing
result.is_high_risk = result.risk_level === 'high' || result.risk_score >= 70;
result.requires_urgent_review = result.risk_level === 'high' || result.red_flags.some(f => f.severity === 'high');

return [{ json: result }];

